import test from "node:test";
import assert from "node:assert/strict";

function formatPitch(pitch) {
  const startupPitchBody = pitch.investmentRationale
    ? `${pitch.startupConcept}\n${pitch.investmentRationale}`
    : pitch.startupConcept;

  return [
    "DELULU CEO",
    "Your worst decisions. Our next unicorn.",
    "",
    "🚀 STARTUP PITCH",
    pitch.startupName,
    startupPitchBody,
    "",
    "📰 FORBES HEADLINE",
    pitch.forbesHeadline,
    "",
    "📉 RISK ANALYSIS",
    pitch.riskAnalysis,
    "",
    "👔 CEO VERDICT",
    pitch.ceoVerdict,
    "",
    "Generated by Delulu CEO — Your worst decisions. Our next unicorn.",
  ].join("\n");
}

test("formatPitch formats pitch response matching the exact PRD template", () => {
  const samplePitch = {
    startupName: "KeyClack Capital",
    startupConcept: "A peer-to-peer micro-leasing platform for artisanal tactile switches.",
    investmentRationale: "High repeat-purchase frequency fueled by late-night forum dopamine.",
    forbesHeadline: "From Desk Clutter to Decacorn: The Founder Monetizing Plastic Clickies",
    riskAnalysis: "Depleting emergency savings re-engineered as aggressive R&D capitalization.",
    ceoVerdict: "You didn't waste $300 on keycaps. You seed-funded an ergonomic sensory ecosystem.",
  };

  const output = formatPitch(samplePitch);

  // Check header
  assert.ok(output.includes("DELULU CEO\nYour worst decisions. Our next unicorn."));

  // Check section titles
  assert.ok(output.includes("🚀 STARTUP PITCH"));
  assert.ok(output.includes("📰 FORBES HEADLINE"));
  assert.ok(output.includes("📉 RISK ANALYSIS"));
  assert.ok(output.includes("👔 CEO VERDICT"));

  // Check real data inserted (no placeholder brackets)
  assert.ok(output.includes("KeyClack Capital"));
  assert.ok(output.includes("A peer-to-peer micro-leasing platform"));
  assert.ok(output.includes("High repeat-purchase frequency"));
  assert.ok(output.includes("From Desk Clutter to Decacorn"));
  assert.ok(output.includes("Depleting emergency savings"));
  assert.ok(output.includes("You didn't waste $300 on keycaps"));

  // Ensure no literal bracket placeholders remain
  assert.equal(output.includes("[Generated"), false);

  // Check footer
  assert.ok(output.endsWith("Generated by Delulu CEO — Your worst decisions. Our next unicorn."));
});
